import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse(`{"title":"css Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"css","tag":"css","title":"css Tag","prev":null,"next":"/tags/css/page/2/","posts":[{"title":"macOS下运行红警2游戏","url":"/posts/2023-12-17-macos-ra2/","date":"2023-12-17 11:20","tags":["css"],"html":"<p>Linux 用户有钱就换 Mac，我也日常使用 Mac 电脑了。但是对于童年回忆的红警 2 游戏，我还是想在 Mac 上玩一玩。这里记录一下在 Mac 上运行红警 2 游戏的过程。</p>\\n<h2 id=\\"下载原版红警-2-游戏\\" tabindex=\\"-1\\">下载原版红警 2 游戏 <a class=\\"header-anchor\\" href=\\"#下载原版红警-2-游戏\\" aria-label=\\"Permalink to &quot;下载原版红警 2 游戏&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>网上应该有很多下载地址，我这里就不提供了。下载完之后，先使用 windows 电脑安装一下，然后把安装好的游戏文件夹拷贝到 Mac 电脑上。</p>\\n<h2 id=\\"安装-crossover\\" tabindex=\\"-1\\">安装 CrossOver <a class=\\"header-anchor\\" href=\\"#安装-crossover\\" aria-label=\\"Permalink to &quot;安装 CrossOver&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>CrossOver 是一款可以在 Mac 上运行 Windows 程序的软件，我们可以使用 CrossOver 来运行红警 2 游戏。CrossOver 有 14 天的试用期，我们可以先下载试用一下。</p>\\n<p>在 CrossOver 中，我们先创建一个 Bottle，然后在 Bottle 中复制安装好的游戏文件夹。之后再配置环境变量，让内部 OS 使用中文运行避免乱码问题，找到 Bottole 的 <code>cxbottle.conf</code></p>\\n<p>在最后的环境变量配置中添加下面的内容：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">[EnvironmentVariables]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">\\"LC_ALL\\"</span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> \\"zh_CN.UTF-8\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><h2 id=\\"下载游戏补丁\\" tabindex=\\"-1\\">下载游戏补丁 <a class=\\"header-anchor\\" href=\\"#下载游戏补丁\\" aria-label=\\"Permalink to &quot;下载游戏补丁&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>由于红警 2 是 2000 年的游戏了，所以在现在的电脑上运行会有一些问题，我们需要下载一些补丁来修复这些问题。</p>\\n<p>下载 cnc-ddraw 补丁，并复制到游戏目录下，然后在 CrossOver 中打开 Wine Configuration，选择 Libraries，添加一个 override，然后输入 ddraw，点击添加并应用。</p>\\n<h2 id=\\"设置分辨率\\" tabindex=\\"-1\\">设置分辨率 <a class=\\"header-anchor\\" href=\\"#设置分辨率\\" aria-label=\\"Permalink to &quot;设置分辨率&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>红警 2 的默认分辨率是 800x600，这个分辨率在现在的电脑上看起来太小了，我们需要修改一下分辨率。并且开启相关的渲染优化，打开 <code>ra2.ini</code> 文件，修改成下面的内容：</p>\\n<div class=\\"language-ini line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ini</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">[Video]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">VideoBackBuffer</span><span style=\\"color:#24292E\\">=no</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">AllowVRAMSidebar</span><span style=\\"color:#24292E\\">=no</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">AllowHiResModes</span><span style=\\"color:#24292E\\">=yes</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ScreenWidth</span><span style=\\"color:#24292E\\">=1728</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ScreenHeight</span><span style=\\"color:#24292E\\">=1117</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">StretchMovies</span><span style=\\"color:#24292E\\">=no</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>上面是我的 MBP 16 寸的分辨率，如果你的电脑分辨率不一样，可以自己修改一下。修改好之后，就可以通过运行 <code>ra2.exe</code> 来启动游戏了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>M1 电脑也是可以运行老游戏的，就是需要折腾一下。希望能帮助大家回忆童年。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.codeweavers.com/support/wiki/mac/faq/cxoffice62_choosedifferentlanguage\\" target=\\"_blank\\" rel=\\"noreferrer\\">Set Windows application to use a different language than the OS default</a></p>\\n<p><a href=\\"https://github.com/FunkyFr3sh/cnc-ddraw/releases\\" target=\\"_blank\\" rel=\\"noreferrer\\">cnc-ddraw</a></p>\\n<p><a href=\\"https://www.codeweavers.com/compatibility/crossover/tips/command-and-conquer-red-alert-2-yuris-revenge/how-to-run-red-alert-2-yuris-revenge-at-full-speed\\" target=\\"_blank\\" rel=\\"noreferrer\\">How to run Red Alert 2</a></p>\\n"},{"title":"嵌套表格如何实现边框合并","url":"/posts/2023-12-03-css-nested-table/","date":"2023-12-03 10:20","tags":["css"],"html":"<p>最近做的项目中有大量表格展示数据的需求，而且还涉及到嵌套表格的情况，这时候就需要考虑如何实现边框合并的问题了。</p>\\n<h2 id=\\"表格的边框合并\\" tabindex=\\"-1\\">表格的边框合并 <a class=\\"header-anchor\\" href=\\"#表格的边框合并\\" aria-label=\\"Permalink to &quot;表格的边框合并&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-css line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">css</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">table</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  border-collapse</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">collapse</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">td</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">th</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  border</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#D73A49\\">px</span><span style=\\"color:#005CC5\\"> solid</span><span style=\\"color:#005CC5\\"> black</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  padding</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#D73A49\\">px</span><span style=\\"color:#005CC5\\"> 20</span><span style=\\"color:#D73A49\\">px</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>我们可以使用上面的 CSS 来描绘表格的边框，而且相邻两个单元格共享同一个边框。但是如果我们在表格中嵌套了另外一个表格，这时候就会出现边框重叠的问题。</p>\\n<h2 id=\\"嵌套表格的边框合并\\" tabindex=\\"-1\\">嵌套表格的边框合并 <a class=\\"header-anchor\\" href=\\"#嵌套表格的边框合并\\" aria-label=\\"Permalink to &quot;嵌套表格的边框合并&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>针对嵌套表格会显示双重边框的问题，我们有两种解决方案，一种是父表格手动删除嵌套表格单元格的边框，另一种是让子表格的边框和父表格的边框重合。\\n第一个实现方式非常简单，只需要在父表格中删除嵌套表格单元格的边框即可，但是这样做会导致父表格的边框和子表格的边框不重合，而且视觉上不美观。\\n第二个实现方式需要在子表格中添加一些 CSS，让子表格的边框和父表格的边框重合。我们可以使用下面的 CSS 来实现：</p>\\n<div class=\\"language-css line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">css</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">table</span><span style=\\"color:#22863A\\"> table</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  width</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">calc</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#005CC5\\"> 2</span><span style=\\"color:#D73A49\\">px</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  margin</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">-1</span><span style=\\"color:#D73A49\\">px</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>通过上面的 CSS，我们可以让子表格的边框和父表格的边框重合，这样就可以解决嵌套表格显示双重边框的问题了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>视觉上让表格边框重合的方法本质上发挥想象力利用 margin 可以设置成负值，然后使用 calc 函数来计算宽度，这样就可以让子表格的边框和父表格的边框重合了。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://codepen.io/acgotaku/pen/zYeMNBg\\" target=\\"_blank\\" rel=\\"noreferrer\\">nested table with collapse border</a></p>\\n"},{"title":"CSS如何处理固定Header哈希标记跳转的问题","url":"/posts/2021-11-20-css-fixed-header/","date":"2021-11-20 21:21","tags":["css"],"html":"<p>有些前端网站一直都有固定的 Header 显示导航，如果我们文档内部有使用 ID 和#符号来帮助跳转到文档某个位置的话，就会被 Header 遮挡住，那我们怎么处理才能让跳转内容正好显示在 Header 下方呢？答案很简单就是让带有 ID 的这个元素占据的空间包含 Header 的高度。</p>\\n<h2 id=\\"padding-和-marging-搭配使用\\" tabindex=\\"-1\\">padding 和 marging 搭配使用 <a class=\\"header-anchor\\" href=\\"#padding-和-marging-搭配使用\\" aria-label=\\"Permalink to &quot;padding 和 marging 搭配使用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>为了保证多占据的空间和 Header 的高度保持一致，我们可以使用 CSS 变量来存储 Header 的高度，这样就能保证一致性。</p>\\n<div class=\\"language-css line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">css</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">h1</span><span style=\\"color:#24292E\\">[</span><span style=\\"color:#6F42C1\\">id</span><span style=\\"color:#24292E\\">] {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  padding-top</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">var</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">--header-height</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  margin-top</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">calc</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">var</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">--header-height</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#005CC5\\"> -1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>margin 可以设定成负数来吃掉撑起来的高度，所以会使元素占据的高度等于显示的高度加上 Header 的高度，这样跳转的时候就能保证内容显示到 Header 下方了。</p>\\n<h2 id=\\"伪元素来撑起空间\\" tabindex=\\"-1\\">伪元素来撑起空间 <a class=\\"header-anchor\\" href=\\"#伪元素来撑起空间\\" aria-label=\\"Permalink to &quot;伪元素来撑起空间&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-css line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">css</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">h1</span><span style=\\"color:#24292E\\">[</span><span style=\\"color:#6F42C1\\">id</span><span style=\\"color:#24292E\\">]</span><span style=\\"color:#6F42C1\\">:before</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  content</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  display</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">block</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  width</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  height</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">var</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">--header-height</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  margin-top</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">calc</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">var</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">--header-height</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#005CC5\\"> -1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>有些时候我们不方便编辑 id 元素本身的 CSS 属性，所以我们可以借助伪元素来实现这个效果。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在 CSS 的世界中，margin 的负值有很多妙用，例如显示列表中如果卡片之间有左右间距，但是最外层却需要和容器保持左右一直，我们也可以使用 margin 的负值来解决这个问题。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://stackoverflow.com/questions/10732690/offsetting-an-html-anchor-to-adjust-for-fixed-header\\" target=\\"_blank\\" rel=\\"noreferrer\\">offsetting an html anchor to adjust for fixed header</a></p>\\n"}]},"relativePath":"tags/css/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/css/index.md"};function l(p,r,o,t,c,i){return a(),n("div")}const b=s(e,[["render",l]]);export{h as __pageData,b as default};
